package com.turboio.androidtests.voice;
import java.io.*;import java.lang.reflect.*;import java.nio.file.*;import java.util.*;import java.nio.charset.StandardCharsets;

public final class MaterialQueueMigrationBridge {
 private static Object call(Object object,String name,Class<?>[] types,Object...args)throws Exception{Class<?> c=object instanceof Class?(Class<?>)object:object.getClass();Method m=c.getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(object instanceof Class?null:object,args);}
 private static void require(boolean b,String code){if(!b)throw new IllegalStateException(code);}
 private static void remove(File file,File root)throws Exception{require(file.getCanonicalPath().equals(root.getCanonicalPath())||file.getCanonicalPath().startsWith(root.getCanonicalPath()+File.separator),"MIGRATION_CLEANUP_SCOPE");require(!Files.isSymbolicLink(file.toPath()),"MIGRATION_CLEANUP_LINK");if(file.isDirectory()){File[] children=file.listFiles();require(children!=null,"MIGRATION_CLEANUP_LIST");for(File child:children)remove(child,root);}require(file.delete(),"MIGRATION_CLEANUP_FAILED");}
 public static String check(File files,ClassLoader legacy,String nonce)throws Exception{
  require(nonce.matches("[a-f0-9]{32}"),"MIGRATION_NONCE_INVALID");File root=new File(files,"material-migration-test-"+nonce);require(root.mkdir(),"MIGRATION_FIXTURE_EXISTS");boolean finished=false;
  try{
   long now=System.currentTimeMillis();byte[] config=WireJson.bytes(WireJson.object("format",MaterialConnection.FORMAT,"base_url","https://synthetic.invalid/v1","owner_id","synthetic-migration","producer_id","synthetic-phone","server_id","synthetic-server","token",String.join("",Collections.nCopies(43,"A")),"token_id","00000000-0000-4000-8000-000000000001","expires_at",TaskWire.now(now+3600000)));
   MaterialConnection connection=MaterialConnection.parse(config,now);Class<?> oldConnection=legacy.loadClass("com.turboio.addon.MaterialConnection"),oldQueue=legacy.loadClass("com.turboio.addon.MaterialOutbox");Object previous=call(oldConnection,"parse",new Class<?>[]{byte[].class,long.class},config,now);Constructor<?> ctor=oldQueue.getDeclaredConstructor(File.class,oldConnection);ctor.setAccessible(true);Object q=ctor.newInstance(root,previous);
   Map<String,Object> body=WireJson.object("material_id","synthetic-queue-migration","revision",1,"base_revision",0,"operation","upsert","source","lifelog","started_at",TaskWire.now(now-1000),"ended_at",TaskWire.now(now),"completeness","partial","text_revision",1,"utterances",new ArrayList<>(),"audio",WireJson.object("state","missing","sha256",null,"object_id",null),"full_text",WireJson.object("format","markdown","text","合成队列迁移验证","origin","asr"),"processing",WireJson.object("transcription_state","unknown","covered_ms",null,"source_ms",null,"speaker","unknown","boundary","unknown","recognition_channel","unknown","user_edited",false),"speakers",new ArrayList<>());
   byte[] event=WireJson.bytes(WireJson.object("schema_version","1.2","event_id","synthetic-migration-event","idempotency_key","synthetic-migration-event","kind","material.revision","producer_id",connection.producer,"created_at",TaskWire.now(now),"expires_at",connection.expires,"body",body));try{call(q,"enqueue",new Class<?>[]{byte[].class},event);}finally{call(q,"close",new Class<?>[0]);}
   Path state=new File(root,"material-outbox/"+connection.binding()+"/state.json").toPath();Map<String,Object> old=WireJson.map(WireJson.read(Files.readAllBytes(state)));long legacySchema=MaterialWire.positive(old.get("schema"));require(legacySchema==1||legacySchema==2,"INSTALLED_READER_NOT_LEGACY");String payload=(String)WireJson.map(WireJson.list(old.get("rows")).get(0)).get("payload");
   try(MaterialOutbox current=new MaterialOutbox(root,connection)){require(current.all().size()==1&&payload.equals(WireJson.map(current.all().get(0)).get("payload")),"MIGRATION_PAYLOAD_CHANGED");}
   byte[] upgraded=Files.readAllBytes(state);require(MaterialWire.positive(WireJson.map(WireJson.read(upgraded)).get("schema"))==3,"MIGRATION_SCHEMA_NOT_UPGRADED");boolean refused=false;try{Object reopened=ctor.newInstance(root,previous);call(reopened,"close",new Class<?>[0]);}catch(InvocationTargetException error){refused="MATERIAL_STORE_INVALID".equals(error.getCause().getMessage());}
   require(refused,"LEGACY_READER_DID_NOT_REFUSE");require(Arrays.equals(upgraded,Files.readAllBytes(state)),"LEGACY_READER_CHANGED_QUEUE");
   try(MaterialOutbox current=new MaterialOutbox(root,connection)){current.enqueue(event);require(current.all().size()==1&&payload.equals(WireJson.map(current.all().get(0)).get("payload")),"FORWARD_REOPEN_LOST_QUEUE");}
   remove(root,root);finished=true;return new String(WireJson.bytes(WireJson.object("legacy_schema",legacySchema,"current_schema",3,"payload_preserved",true,"installed_legacy_reader_refused_without_overwrite",true,"forward_reopen_and_replay_preserved",true,"fixture_removed",true)),StandardCharsets.UTF_8);
  }finally{if(!finished&&root.exists())remove(root,root);}
 }
}
